package remote

import (
	"crypto/rand"
	"encoding/base64"
	"errors"
	"maps"
	"strings"
)

const ssAEADGuardEmail = "mxioc-ss-aead-empty-guard"

func ssAEADTemplateMethod(template string) string {
	switch template {
	case "ss-aes-128-gcm":
		return "aes-128-gcm"
	case "ss-aes-256-gcm":
		return "aes-256-gcm"
	case "ss-chacha20-poly1305":
		return "chacha20-ietf-poly1305"
	}
	return ""
}

// Only secrets generated by the Go-managed template are accepted for writes.
// Existing arbitrary-password SS inbounds remain available through read/export.
func managedAEADSecret(secret string) bool {
	raw, err := base64.RawURLEncoding.DecodeString(secret)
	return err == nil && len(raw) == 32 && base64.RawURLEncoding.EncodeToString(raw) == secret
}

func guardedSSAEADSettings(row Record) (Record, error) {
	settings, err := object(row["settings"])
	method, root, guard := value(settings["method"]), value(settings["password"]), value(row["goSSAEADGuard"])
	_, modern := row["goSS2022Guard"]
	if err != nil || modern || row["protocol"] != "shadowsocks" || value(row["goCreateKey"]) == "" ||
		(method != "aes-128-gcm" && method != "aes-256-gcm" && method != "chacha20-ietf-poly1305") ||
		!managedAEADSecret(root) || !managedAEADSecret(guard) || root == guard {
		return nil, errors.New("Shadowsocks AEAD 托管认证配置无效")
	}
	for key := range settings {
		if key != "method" && key != "password" && key != "clients" && !(key == "network" && settings[key] == "tcp,udp") {
			return nil, errors.New("Shadowsocks AEAD 托管认证扩展尚未适配")
		}
	}
	clients, ok := settings["clients"].([]any)
	if !ok {
		return nil, errors.New("Shadowsocks AEAD 托管用户列表无效")
	}
	keys, names := map[string]bool{root: true, guard: true}, map[string]bool{ssAEADGuardEmail: true}
	for _, raw := range clients {
		client, ok := raw.(Record)
		if !ok {
			return nil, errors.New("Shadowsocks AEAD 托管用户格式无效")
		}
		key, name := value(client["password"]), value(client["email"])
		// The per-user method is fixed to the endpoint method. EndpointIdentity
		// binds that method, so changing it cannot reuse an existing user binding.
		if client["method"] != method || !managedAEADSecret(key) || keys[key] || names[name] || name == "" || len(name) > 1024 || strings.ContainsAny(name, "\r\n\x00") || strings.Contains(name, ">>>") {
			return nil, errors.New("Shadowsocks AEAD 用户凭据无效或重复")
		}
		if raw, present := client["enable"]; present {
			if _, ok := raw.(bool); !ok {
				return nil, errors.New("Shadowsocks AEAD 用户启用状态无效")
			}
		}
		keys[key], names[name] = true, true
	}
	stream, err := object(row["streamSettings"])
	if err != nil || (value(stream["security"]) != "" && stream["security"] != "none") ||
		(value(stream["network"]) != "" && stream["network"] != "tcp" && stream["network"] != "raw") {
		return nil, errors.New("Shadowsocks AEAD 托管传输尚未适配")
	}
	return settings, nil
}

func ssAEADNativeClients(row Record, clients []any) ([]any, error) {
	settings, err := guardedSSAEADSettings(row)
	if err != nil {
		return nil, err
	}
	if len(clients) > 0 {
		return clients, nil
	}
	return []any{Record{"email": ssAEADGuardEmail, "method": settings["method"], "password": row["goSSAEADGuard"]}}, nil
}

func buildStandaloneSSAEADTemplate(payload Record) (Record, error) {
	method := ssAEADTemplateMethod(templateName(payload))
	if method == "" {
		return nil, errors.New("Shadowsocks AEAD 模板无效")
	}
	base := maps.Clone(payload)
	base["template"] = "vmess-tcp"
	row, err := buildInboundTemplate(base, "")
	if err != nil {
		return nil, err
	}
	secrets := make([]byte, 64)
	if _, err := rand.Read(secrets); err != nil {
		return nil, err
	}
	row["protocol"] = "shadowsocks"
	row["settings"] = Record{"method": method, "password": base64.RawURLEncoding.EncodeToString(secrets[:32]), "network": "tcp,udp", "clients": []any{}}
	row["goSSAEADGuard"] = base64.RawURLEncoding.EncodeToString(secrets[32:])
	return row, nil
}
